glsl:
vec4 effect(vec2 uv) {
  vec4 c = getColor(uv);
  float s = mix(220.0, 70.0, uAmount);
  mat2 r = mat2(0.7071, -0.7071, 0.7071, 0.7071);
  vec2 p = r * (uv * vec2(uRatio, 1.0) * s);
  vec2 cell = fract(p) - 0.5;
  vec2 cid = floor(p) + 0.5;
  vec2 cuv = (transpose(r) * cid) / s / vec2(uRatio, 1.0);
  vec3 cc = getColor(cuv).rgb;
  float rad = sqrt(1.0 - luma(cc)) * 0.6;
  float dotv = smoothstep(rad, rad - 0.08, length(cell));
  vec3 ink = mix(vec3(0.98, 0.96, 0.9), cc * 0.6, dotv);
  return vec4(mix(c.rgb, ink, uAmount), c.a);
}
